public class Car
{
    // Fields (state)
    public string Make;
    public string Model;
    public int Year;

    // Method (behavior)
    public void Start()
    {
        Console.WriteLine($"{Make} {Model} is starting");
    }
}

// Creating objects
var car1 = new Car { Make = "Toyota", Model = "Camry", Year = 2023 };
var car2 = new Car { Make = "Honda", Model = "Civic", Year = 2022 };

car1.Start(); // Toyota Camry is starting
car2.Start(); // Honda Civic is starting
